// Tier is percentile-based (see effTier computation) not a fixed number -- "high" is
// literally "top third of what's currently visible", so it stays meaningful across levels.
export const effTierColor = tier => tier === "high" ? "#22c55e" : tier === "mid" ? "#eab308" : "#ef4444";
export function formatExpPerHour(v) {
  if (v == null) return "--";
  if (v >= 1_000_000) return (v / 1_000_000).toFixed(1) + "M";
  if (v >= 1000) return (v / 1000).toFixed(1) + "K";
  return Math.round(v).toString();
}
// Picks black/white text for a #rrggbb background by relative luminance (WCAG-style),
// so badge colors can stay bright/varied without hand-tuning text color per badge --
// bright backgrounds (yellow, emerald, sky blue) get black text, dark ones get white.
export function contrastText(hex) {
  const n = parseInt(hex.slice(1), 16);
  const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance > 0.6 ? "#000" : "#fff";
}
const badge = (label, val, color, textColor = contrastText(color)) => (
  <span style={{ background:color, color:textColor, borderRadius:4, padding:"1px 7px", fontSize:11, fontWeight:700, marginRight:4 }}>
    {label}: {val}
  </span>
);

// -- Variable-height virtualized list -----------------------------------------
// Renders only the items currently near the viewport (plus overscan), instead of
// mounting the entire filtered list at once. This matters a lot here because each
// monster card can include several real spawn-map thumbnail images -- with 1000+
// monsters, mounting everything at once would mean loading potentially thousands
// of images into the DOM simultaneously.
//
// Card heights vary a lot (a curated monster with heal analysis and 10 spawn map
// thumbnails vs. a plain auto-generated row), so this uses *measured* heights
// rather than a single fixed row height: unmeasured items use `estimatedItemHeight`
// as a placeholder, and get corrected to their real height after they first mount,
// which nudges the layout to the right total height without a full remeasure pass.
function VirtualList({ items, renderItem, estimatedItemHeight = 190, overscan = 6 }) {
  const [scrollY, setScrollY] = useState(typeof window !== "undefined" ? window.scrollY : 0);
  const [viewportH, setViewportH] = useState(typeof window !== "undefined" ? window.innerHeight : 800);
  const [containerTop, setContainerTop] = useState(0);
  const heightsRef = useRef(new Map()); // index -> measured height (persists across renders)
  const [, forceRerender] = useState(0);
  const containerRef = useRef(null);

  useEffect(() => {
    const onScroll = () => setScrollY(window.scrollY);
    const onResize = () => setViewportH(window.innerHeight);
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onResize);
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onResize);
    };
  }, []);

  useEffect(() => {
    if (containerRef.current) {
      setContainerTop(containerRef.current.getBoundingClientRect().top + window.scrollY);
    }
  }, [items.length]);

  // Reset measured heights when the underlying item list changes (new filter/sort),
  // since indices no longer correspond to the same items.
  useEffect(() => {
    heightsRef.current.clear();
    forceRerender(n => n + 1);
  }, [items]);

  const getHeight = (i) => heightsRef.current.get(i) ?? estimatedItemHeight;

  // Prefix-sum offsets. O(n) per render is fine at this scale (a few thousand items,
  // recomputed only on scroll/resize/measurement, not on every keystroke).
  const offsets = [];
  let acc = 0;
  for (let i = 0; i < items.length; i++) {
    offsets.push(acc);
    acc += getHeight(i);
  }
  const totalHeight = acc;

  const viewTop = Math.max(0, scrollY - containerTop);
  const viewBottom = viewTop + viewportH;

  // binary search for first index whose offset+height >= viewTop
  let lo = 0, hi = items.length - 1, startIndex = 0;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (offsets[mid] + getHeight(mid) < viewTop) { lo = mid + 1; } else { startIndex = mid; hi = mid - 1; }
  }
  let endIndex = startIndex;
  while (endIndex < items.length && offsets[endIndex] < viewBottom) endIndex++;

  startIndex = Math.max(0, startIndex - overscan);
  endIndex = Math.min(items.length, endIndex + overscan);

  const visible = items.slice(startIndex, endIndex);

  return (
    <div ref={containerRef} style={{ position: "relative", height: totalHeight }}>
      {visible.map((item, vi) => {
        const i = startIndex + vi;
        return (
          <MeasuredRow key={item.id} index={i} top={offsets[i]}
            onMeasure={(h) => {
              const prev = heightsRef.current.get(i);
              if (prev === undefined || Math.abs(prev - h) > 2) {
                heightsRef.current.set(i, h);
                forceRerender(n => n + 1);
              }
            }}>
            {renderItem(item, i)}
          </MeasuredRow>
        );
      })}
    </div>
  );
}

function MeasuredRow({ index, top, onMeasure, children }) {
  const ref = useRef(null);
  useEffect(() => {
    if (ref.current) {
      const h = ref.current.getBoundingClientRect().height;
      if (h > 0) onMeasure(h);
    }
  });
  return (
    <div ref={ref} style={{ position: "absolute", top, left: 0, right: 0, paddingBottom: 8 }}>
      {children}
    </div>
  );
}


// Small labeled row for grouping filter chips by category (Level Range, Elemental
// Weakness, Efficiency, Casts, Type).
function FilterRow({ label, hint, children }) {
  return (
    <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
      <span style={{ fontSize:10, color:"#6b7280", letterSpacing:1, minWidth:110 }} title={hint}>
        {label.toUpperCase()}:
      </span>
      <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
        {children}
      </div>
    </div>
  );
}

function MonsterCard({ m, i, selected, setSelected, setWorldMapMapId, CHAR, dmg, activeSkill, isHeal, healTargets, mpEaterLvl, sessionMins, potionKey }) {
  return (
            <div key={m.id} onClick={()=>setSelected(selected===m.id?null:m.id)}
              style={{ background:"#161b22", border:`1px solid ${selected===m.id?"#7c3aed":i===0&&!selected?"#7c3aed44":"#21262d"}`, borderRadius:8, padding:"10px 14px", cursor:"pointer", transition:"border-color 0.15s" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:10 }}>
                <img src={mobImg(m.id)} alt=""
                  style={{ width:36, height:36, objectFit:"contain", imageRendering:"pixelated", background:"#0d1117", border:"1px solid #21262d", borderRadius:4, flexShrink:0 }}
                  onError={e=>{
                    if (!e.target.dataset.triedFallback) {
                      e.target.dataset.triedFallback = "1";
                      const wzid = mobWzId(m);
                      if (wzid) { e.target.src = mobImgFallback(wzid); }
                      else { e.target.style.display = "none"; }
                    } else {
                      e.target.style.display = "none";
                    }
                  }} />
                <div style={{ flex:1, minWidth:0 }}>
                  <span style={{ fontSize:14, fontWeight:700, color:"#e2e8f0" }}>{m.name}</span>
                  {m.boss && <span style={{ marginLeft:8, background:"#7f1d1d", color:"#fca5a5", fontSize:10, padding:"1px 6px", borderRadius:3, fontWeight:700 }}>BOSS</span>}
                  {m.undead && <span style={{ marginLeft:6, background:"#14532d", color:"#86efac", fontSize:10, padding:"1px 6px", borderRadius:3, fontWeight:700 }}>+ UNDEAD</span>}
                  {STAT_VERIFIED_IDS.has(m.id) && <span style={{ marginLeft:6, background:"#1e3a5f", color:"#7dd3fc", fontSize:10, padding:"1px 6px", borderRadius:3, fontWeight:700 }} title={m.auto ? "Cosmic v83 dump entry -- verified via a diverse spot-check against legends.ml (48 monsters checked across the full level range, 9 with a systematic error corrected) plus the same-source guarantee already confirmed for the individually-checked set, not an individual re-check of this specific monster" : "HP/EXP/ATK/DEF individually spot-checked against MapleLegends' real values via legends.ml + Cosmic v83 crosswalk"}>[OK] STATS VERIFIED</span>}
                  {m.auto && !STAT_VERIFIED_IDS.has(m.id) && <span style={{ marginLeft:6, background:"#3f2d0d", color:"#fbbf24", fontSize:10, padding:"1px 6px", borderRadius:3, fontWeight:700 }} title="Sourced from the Cosmic v83 dump but NOT verified -- this specific entry failed or couldn't complete a legends.ml cross-check (see monsterDb.js's header comment) and may have wrong stats">NORMAL</span>}
                  <div style={{ fontSize:11, color:"#6b7280" }}>Lv{m.level} x {m.location}</div>
                </div>
                <div style={{ textAlign:"right", flexShrink:0 }}
                  title="Exp per hour of continuous casting at your current stats/level -- top/middle/bottom third of what's currently shown, not a fixed number">
                  <span style={{ fontSize:20, fontWeight:700, color:effTierColor(m.effTier) }}>{formatExpPerHour(m.primaryExpPerHour)}</span>
                  <div style={{ fontSize:9, color:"#4b5563" }}>EXP/HR</div>
                </div>
              </div>

              <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:"4px 12px", fontSize:11, marginTop:8 }}>
                <div><span style={{color:"#6b7280"}}>HP </span><span style={{color:"#f87171"}}>{m.hp.toLocaleString()}</span></div>
                <div><span style={{color:"#6b7280"}}>M.DEF </span><span style={{color:m.mDef>0?"#f97316":"#6b7280"}}>{m.mDef}</span></div>
                <div><span style={{color:"#6b7280"}}>EXP </span><span style={{color:"#4ade80"}}>{m.exp2x}</span><span style={{color:"#374151"}}> (2x)</span></div>
                <div><span style={{color:"#6b7280"}}>Meso </span><span style={{color:"#fcd34d"}}>~{Math.round(m.wAtk*0.45)}-{Math.round(m.wAtk*0.7)}</span></div>
                <div><span style={{color:"#6b7280"}}>W.ATK </span><span>{m.wAtk}</span></div>
                <div><span style={{color:"#6b7280"}}>Avoid </span><span>{m.avoid}</span></div>
                <div><span style={{color:"#6b7280"}}>ACC req </span><span>{m.acc}</span></div>
                <div><span style={{color:"#6b7280"}}>Eff.HP </span><span style={{color:"#fbbf24"}}>{m.effHP}</span></div>
              </div>

              {/* Combat */}
              <div style={{ marginTop:8, padding:"6px 10px", background:"#0d1117", borderRadius:4, borderLeft:`3px solid ${m.elementalMult===0?"#6b7280":m.hits===1?"#22c55e":m.hits===2?"#eab308":"#ef4444"}`, fontSize:11, display:"flex", gap:14, flexWrap:"wrap" }}>
                {m.elementalMult === 0 ? (
                  <span><span style={{color:"#6b7280"}}>CASTS: </span><span style={{color:"#9ca3af", fontWeight:700}}>N/A -- IMMUNE to {activeSkill.element}</span></span>
                ) : (
                  <span><span style={{color:"#6b7280"}}>CASTS: </span><span style={{color:m.hits===1?"#22c55e":m.hits===2?"#eab308":"#ef4444", fontWeight:700}}>{m.hits}{m.hits===1?" [OK] ONE-SHOT":""}</span></span>
                )}
                <span><span style={{color:"#6b7280"}}>YOUR DMG: </span>{(m.dmgMin*activeSkill.hitsPerCast).toFixed(0)}-{(m.dmgMax*activeSkill.hitsPerCast).toFixed(0)}/cast ({m.dmgMin.toFixed(0)}-{m.dmgMax.toFixed(0)}/hit x{activeSkill.hitsPerCast}) vs {m.effHP}
                  {activeSkill.element && m.elementalMult !== 1 && (
                    <span style={{color: m.elementalMult > 1 ? "#4ade80" : m.elementalMult === 0 ? "#9ca3af" : "#f87171"}}> ({m.elementalMult}x {m.elementalMult > 1 ? "weak" : m.elementalMult === 0 ? "immune" : "resist"})</span>
                  )}
                </span>
                {m.elementalMult !== 0 && (
                  <span><span style={{color:"#6b7280"}}>MP/{isHeal ? "CAST" : "KILL"}: </span><span style={{color:"#0ea5e9"}}>{isHeal ? m.mpCostPerCast : m.hits*m.mpCostPerCast}</span>
                    {mpEaterLvl > 0 && m.mp > 0 && (
                      <span style={{color:"#60a5fa"}}> (net ~{(isHeal ? m.mcNetMp : m.mcNetMp * m.hits).toFixed(1)} w/MPE {(m.mcAnyProc*100).toFixed(0)}% proc)</span>
                    )}
                  </span>
                )}
                {m.hits > 1 && m.oneshotLvl && (
                  <span><span style={{color:"#6b7280"}}>ONE-SHOT @ </span><span style={{color:"#a78bfa"}}>Lv{m.oneshotLvl}</span> <span style={{color:"#374151"}}>({m.oneshotLvl-CHAR.level} lvls)</span></span>
                )}
              </div>

              {/* Elements */}
              {(m.weak!=="-"||m.strong!=="-"||m.immune!=="-") && (
                <div style={{ marginTop:6, fontSize:11, display:"flex", gap:12 }}>
                  {m.weak!=="-"&&<span style={{color:"#4ade80"}}>[L] Weak: {m.weak}</span>}
                  {m.strong!=="-"&&<span style={{color:"#f87171"}}>[S] Strong: {m.strong}</span>}
                  {m.immune!=="-"&&<span style={{color:"#9ca3af"}}>[I] Immune: {m.immune}</span>}
                </div>
              )}

              {/* Session profit panel */}
              <div style={{ marginTop:8, padding:"8px 10px", background:"#0d1117", borderRadius:4, border:"1px solid #21262d", fontSize:11 }}>
                <div style={{ color:"#f59e0b", fontWeight:700, marginBottom:4, letterSpacing:1 }}>
                  SESSION PROFIT ({sessionMins}min)
                </div>
                <div>
                  <div style={{ color:"#6b7280", fontSize:9, marginBottom:2, letterSpacing:1 }}>{activeSkill.label.toUpperCase()} ({activeSkill.castTimeSec}s/{isHeal ? "cast" : "kill"})</div>
                  <div style={{ display:"flex", gap:12, flexWrap:"wrap" }}>
                    <span><span style={{color:"#6b7280"}}>Kills: </span><span>{m.mcSession.kills.toLocaleString()}</span></span>
                    <span><span style={{color:"#6b7280"}}>Pots: </span><span style={{color:"#f87171"}}>{m.mcSession.potCost.toLocaleString()}</span>
                      {m.mcSession.hpPotCost > 0 && (
                        <span style={{color:"#4b5563"}}> ({m.mcSession.mpPotsNeeded.toLocaleString()} MP + {m.mcSession.hpPotsNeeded.toLocaleString()} HP pots)</span>
                      )}
                    </span>
                    <span><span style={{color:"#6b7280"}}>Income: </span><span style={{color:"#86efac"}}>{m.mcSession.income.toLocaleString()}</span></span>
                    <span><span style={{color:"#6b7280"}}>Profit: </span>
                      <span style={{color: m.mcSession.profit >= 0 ? "#22c55e" : "#ef4444", fontWeight:700}}>
                        {m.mcSession.profit >= 0 ? "+" : ""}{m.mcSession.profit.toLocaleString()}
                      </span>
                    </span>
                    <span style={{color:"#a78bfa", fontWeight:700}}>
                      +{m.mcSession.levelsGained} lvl{m.mcSession.levelsGained !== 1 ? "s" : ""}
                      {" "}{m.mcSession.leftoverPct.toFixed(2)}% into Lv{m.mcSession.finalLevel}
                    </span>
                  </div>
                </div>
                <div style={{ color:"#374151", fontSize:8, marginTop:4 }} title={m.incomeIsEstimated ? "No drop_data rows matched this monster -- using the dataset-wide average income/kill as a fallback" : "Mesos drop EV + sellable item/equip drop EV, from real drop tables + NPC sell prices"}>
                  ~{Math.round(m.incomePerKill)} mesos/kill (drop+etc+equip EV{m.incomeIsEstimated ? ", est." : ""}) x {POTIONS[potionKey || "bluePotion"].label}
                </div>
              </div>

              {m.spawnMaps && (
                <div style={{ marginTop:8 }}>
                  <div style={{ fontSize:10, color:"#4b5563", marginBottom:4, letterSpacing:1 }}>
                    [M] SPAWN MAPS (click for full map)
                    {m.spawnMaps.some(s=>s.verified) && (
                      <span style={{ marginLeft:8, color:"#4ade80" }}>[OK] MAP.WZ VERIFIED</span>
                    )}
                  </div>
                  <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                    {m.spawnMaps.map(({name, mapId, count, verified}) => (
                      <div key={mapId} onClick={()=>setWorldMapMapId(mapId)}
                        title={`${name} (${count} spawns)${verified ? " - Map.wz verified" : " - curated/unverified"}${MAP_PLATFORM_DATA[mapId] ? " - " + MAP_PLATFORM_DATA[mapId].notes : ""} -- click to expand`}
                        style={{ display:"block", border:`1px solid ${verified ? "#166534" : "#30363d"}`, borderRadius:4, overflow:"hidden", cursor:"pointer", flexShrink:0, transition:"border-color 0.15s", position:"relative" }}
                        onMouseEnter={e=>e.currentTarget.style.borderColor="#7c3aed"}
                        onMouseLeave={e=>e.currentTarget.style.borderColor=verified?"#166534":"#30363d"}>
                        <img src={mapImg(mapId)} alt={name}
                          style={{ width:120, height:72, objectFit:"cover", display:"block", background:"#0d1117", imageRendering:"pixelated" }}
                          onError={e=>{
                            if (!e.target.dataset.triedFallback) {
                              e.target.dataset.triedFallback = "1";
                              e.target.src = mapImgFallback(mapId);
                            } else {
                              e.target.style.display="none";
                              e.target.nextSibling.style.display="flex";
                            }
                          }} />
                        <div style={{ display:"none", width:120, height:72, background:"#161b22", alignItems:"center", justifyContent:"center", fontSize:9, color:"#6b7280", textAlign:"center", padding:"4px" }}>
                          {verified ? "" : name}
                        </div>
                        {/* External link to legends.ml full map page -- kept small so it doesn't
                            crowd out the MC/HL score and map-quality badges on the thumbnail */}
                        <a href={mapUrl(mapId)} target="_blank" rel="noopener noreferrer" onClick={e=>e.stopPropagation()}
                          title="Open on legends.ml"
                          style={{ position:"absolute", bottom:3, right:3, background:"#0d1117cc", color:"#9ca3af", fontSize:10, fontWeight:700, width:14, height:14, display:"flex", alignItems:"center", justifyContent:"center", borderRadius:3, textDecoration:"none", lineHeight:1 }}>
                          [+]
                        </a>
                        {/* Spawn count badge */}
                        <div style={{ position:"absolute", top:3, right:3, background:verified?"#166534":"#7c3aed", color:"#fff", fontSize:9, fontWeight:700, padding:"1px 5px", borderRadius:3, letterSpacing:0.5 }}>
                          x{count}
                        </div>
                        {/* Heal coverage badge (undead maps only, hand-curated subset) */}
                        {m.undead && MAP_PLATFORM_DATA[mapId] && (
                          <div style={{ position:"absolute", top:3, left:3, background:healCoverageColor(MAP_PLATFORM_DATA[mapId].healCoverage), color:"#000", fontSize:9, fontWeight:700, padding:"1px 5px", borderRadius:3 }}>
                            {layoutIcon(MAP_PLATFORM_DATA[mapId].layout)} {MAP_PLATFORM_DATA[mapId].healCoverage}/6
                          </div>
                        )}
                        <div style={{ background:"#0d1117", padding:"2px 5px", fontSize:9, color:"#9ca3af", maxWidth:120, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }} title={name}>
                          {name}
                        </div>
                        {/* Auto-computed training score for the ACTIVE skill's own hitbox archetype
                            (see classSkills.js's mapScoreArchetype/SCORE_FIELD and tools/
                            extract_skill_map_scores.mjs) -- "ranged"/"melee" single-target skills
                            get mcScore/meleeScore, same-platform AoE skills (Slash Blast, Somersault
                            Kick, Thunder Bolt, etc.) get aoeScore, and Heal (the only skill whose box
                            reaches adjacent floors) gets healScore. All 4 already fold in the rope/
                            ladder travel penalty and the low-spawn-supply penalty below -- the *Raw
                            fields are the pre-penalty geometry-only scores. */}
                        {MAP_SCORES[mapId] && (() => {
                          const field = SCORE_FIELD[activeSkill.mapScoreArchetype];
                          const rawField = SCORE_FIELD_RAW[activeSkill.mapScoreArchetype];
                          const score = MAP_SCORES[mapId][field];
                          const raw = MAP_SCORES[mapId][rawField];
                          return (
                            <div style={{ background:scoreColor(score), color:"#000", fontSize:8, fontWeight:700, padding:"1px 5px", textAlign:"center" }}
                              title={`${activeSkill.label} training score for this map${raw > score ? ` -- ${raw}/5 before rope/ladder travel and low-spawn penalties` : ""}`}>
                              {SCORE_LABEL[activeSkill.mapScoreArchetype]} {score}/5
                            </div>
                          );
                        })()}
                        {/* Rope-heavy warning: flagged when the score above was actually docked for
                            forced rope/ladder travel between mob-bearing floors (see ropeCoverageRatio
                            in MAP_SCORES, tools/extract_rope_data.mjs) -- e.g. Dungeon: Damp Tree-Forest. */}
                        {MAP_SCORES[mapId] && MAP_SCORES[mapId].ropeCount > 0 && MAP_SCORES[mapId].mcScoreRaw > MAP_SCORES[mapId].mcScore + (MAP_SCORES[mapId].lowSpawnPenalty || 0) && (
                          <div style={{ background:"#3a2412", color:"#f59e0b", fontSize:8, fontWeight:700, padding:"1px 4px", textAlign:"center", letterSpacing:0.5 }}
                            title={`${MAP_SCORES[mapId].ropeCount} rope/ladder segments cover ${Math.round(MAP_SCORES[mapId].ropeCoverageRatio*100)}% of this map's vertical span -- slow to traverse between farming floors`}>
                            [~] ROPE-HEAVY
                          </div>
                        )}
                        {/* Low-spawn warning: this map's total mob population (mobCount) is small enough
                            that a farming session is likely to clear it faster than monsters respawn,
                            leading to idle downtime -- see tools/apply_spawn_penalty.mjs. */}
                        {MAP_SCORES[mapId] && MAP_SCORES[mapId].lowSpawnPenalty > 0 && (
                          <div style={{ background:"#3a1212", color:"#f87171", fontSize:8, fontWeight:700, padding:"1px 4px", textAlign:"center", letterSpacing:0.5 }}
                            title={`Only ${MAP_SCORES[mapId].mobCount} monster${MAP_SCORES[mapId].mobCount===1?"":"s"} spawn on this map at once -- likely to be cleared faster than it respawns, leaving you idle`}>
                            [!] LOW SPAWN
                          </div>
                        )}
                        {/* No-portal-path warning: BFS over the real portal graph from every town
                            found no walkable path into this map -- see tools/extract_portals.mjs.
                            Caveat: NPC-dialogue warps (most Party Quests) aren't portals, so this
                            can false-positive on real, reachable content. */}
                        {isUnreachableMap(mapId) && (
                          <div style={{ background:"#241a3a", color:"#c4b5fd", fontSize:8, fontWeight:700, padding:"1px 4px", textAlign:"center", letterSpacing:0.5 }}
                            title="No walkable portal path found from any town to this map. It may only be reachable via an NPC dialogue warp (common for Party Quests) rather than a physical portal -- treat this as a strong signal, not certainty.">
                            [?] NO PORTAL PATH
                          </div>
                        )}
                        {/* Platform notes on hover via title - also show layout inline */}
                        {MAP_PLATFORM_DATA[mapId] && (
                          <div style={{ background:"#161b22", padding:"2px 5px", fontSize:8, color: MAP_PLATFORM_DATA[mapId].estimated ? "#4b5563" : "#6b7280", maxWidth:120, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                            {MAP_PLATFORM_DATA[mapId].platforms}p {MAP_PLATFORM_DATA[mapId].layout}{MAP_PLATFORM_DATA[mapId].estimated ? " *est" : ""}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
  );
}

export default function App() {
  // -- Class/skill selection ---------------------------------------------------
  // Which primary attacking skill the whole app's damage/kill/session math is
  // driven by -- see src/lib/classSkills.js. Only skills with verified: true have
  // a real formula; the rest are disabled in the selector rather than guessed.
  const [activeSkillKey, setActiveSkillKey] = useState("magicClaw");
  // null = "Show All Skills" (every class's chips shown at once, the original
  // behavior); otherwise one of CLASS_LIST below, narrowing the skill row to
  // just that class's chips. Purely a display filter -- it doesn't change
  // activeSkillKey itself, so switching class filters never surprises you by
  // silently swapping which skill's damage math is currently driving the list.
  const [classFilter, setClassFilter] = useState(null);
  const activeSkill = SKILLS[activeSkillKey];

  // -- Configurable character panel ------------------------------------------
  // str/dex feed the physical classes' skills (Power Strike, Slash Blast, Double
  // Shot, Lucky Seven, Somersault Kick -- see classSkills.js), luk/int the magic
  // ones (Magic Claw, Heal, Lucky Seven's LUK-primary claw). Every skill reads
  // from the same CHAR object, so switching classes doesn't require re-plumbing.
  const [charLevel, setCharLevel] = useState(DEFAULT_CHAR.level);
  const [charStr, setCharStr] = useState(DEFAULT_CHAR.str);
  const [charDex, setCharDex] = useState(DEFAULT_CHAR.dex);
  const [charInt, setCharInt] = useState(DEFAULT_CHAR.int);
  const [charLuk, setCharLuk] = useState(DEFAULT_CHAR.luk);
  const [charWeaponAtk, setCharWeaponAtk] = useState(DEFAULT_CHAR.weaponAtk);
  const [charMpMax, setCharMpMax] = useState(DEFAULT_CHAR.mpMax);
  const [charHpMax, setCharHpMax] = useState(DEFAULT_CHAR.hpMax);
  const [charDef, setCharDef] = useState(DEFAULT_CHAR.def);
  const [charExpPct, setCharExpPct] = useState(DEFAULT_CHAR.expPct);
  const [charPanelOpen, setCharPanelOpen] = useState(false);

  // Derived char object used everywhere
  const CHAR = useMemo(() => ({
    level: charLevel, str: charStr, dex: charDex, int: charInt, luk: charLuk,
    weaponAtk: charWeaponAtk, mpMax: charMpMax, hpMax: charHpMax, def: charDef,
  }), [charLevel, charStr, charDex, charInt, charLuk, charWeaponAtk, charMpMax, charHpMax, charDef]);

  const isHeal = activeSkillKey === "heal";
  const [healLvl, setHealLvl] = useState(0);
  const [healTargets, setHealTargets] = useState(3);

  // Heal's formula takes a skill level (healLvl, from its own slider below) in addition
  // to stats, unlike every other skill's formula(stats)-only shape -- this wrapper binds
  // healLvl so the rest of the app (dmg, oneshotLevel) can keep treating it generically.
  const dmgFn = useMemo(
    () => isHeal ? (stats => activeSkill.formula(stats, healLvl)) : activeSkill.formula,
    [isHeal, activeSkill, healLvl]
  );

  // null when the active skill has no verified formula, or Heal is selected at level 0
  // (unlearned) -- callers must handle this (the monster list shows nothing instead of
  // guessing numbers for an uncast skill).
  const dmg = useMemo(
    () => (activeSkill.verified && !(isHeal && healLvl === 0)) ? dmgFn(CHAR) : null,
    [CHAR, activeSkill, dmgFn, isHeal, healLvl]
  );

  const [query, setQuery] = useState("");
  const [levelMin, setLevelMin] = useState(1);
  const [levelMax, setLevelMax] = useState(100);
  const [bossOnly, setBossOnly] = useState(false);
  const [undeadOnly, setUndeadOnly] = useState(false);
  const [autoOnly, setAutoOnly] = useState(false);
  const [hideUnknownLoc, setHideUnknownLoc] = useState(true); // hides m.location === "Location unknown" -- mostly event/unused mobs, pure noise
  const [hideNoMapData, setHideNoMapData] = useState(true); // hides monsters with no spawnMapsFor() data at all -- unresolved crosswalk entries, not real farmable content
  const [zoneFilter, setZoneFilter] = useState(null); // null = all zones; else a ZONE_NAMES entry -- monster matches if ANY of its spawn maps is in that zone
  const [hideRopeHeavy, setHideRopeHeavy] = useState(false); // hides monsters whose EVERY known spawn map is rope/ladder-heavy
  const [hideLowSpawn, setHideLowSpawn] = useState(false); // hides monsters whose EVERY known spawn map has low total mob supply
  const [hideUnreachable, setHideUnreachable] = useState(false); // hides monsters whose EVERY known spawn map has no portal-graph path from a town
  const [minMapScore, setMinMapScore] = useState(0); // 0 = off; else hides monsters whose EVERY spawn map's score (for the active skill's own archetype) is below this
  const [weakFilter, setWeakFilter] = useState(null); // e.g. "Fire", "Holy", "Lightning" -- exact match on m.weak
  const [effFilter, setEffFilter] = useState(null); // "low" | "mid" | "high" -- bucketed on m.ratio, matches effColor thresholds
  const [castsFilter, setCastsFilter] = useState(null); // [lo,hi] -- bucketed on m.hits (Magic Claw casts to kill)
  const [sortBy, setSortBy] = useState("efficiency");
  const [sortDir, setSortDir] = useState(1); // 1 = ascending, -1 = descending
  const [selected, setSelected] = useState(null);
  const [worldMapMapId, setWorldMapMapId] = useState(null);
  const [mpEaterLvl, setMpEaterLvl] = useState(0);
  const [sessionMins, setSessionMins] = useState(60);
  const [potionKey, setPotionKey] = useState("bluePotion");
  // Incoming damage / HP potion usage -- see formulas.js's incomingDamagePerHit
  // header comment for what this does and doesn't model. Defaults ON: warriors
  // are melee and always in range (the "core part of warrior costs" case), and
  // defaulting every class to modeling damage is the safer assumption for a
  // training-spot profit estimate -- players who genuinely take no damage (kiting,
  // pure ranged/safe-distance play) can turn it off, per the toggle's own purpose.
  const [takeDamage, setTakeDamage] = useState(true);
  const [hitIntervalSec, setHitIntervalSec] = useState(4); // 3-5s estimate, see formulas.js
  const [hpPotionKey, setHpPotionKey] = useState("orangePotion");
  // Magic Guard (Magician 1st job, any branch -- see formulas.js's
  // applyMagicGuard/MAGIC_GUARD_LEVELS) converts a % of incoming damage into
  // MP loss instead of HP loss, so it only makes sense to model for Magician
  // skills -- gated the same way Heal's own controls are gated to isHeal.
  const [magicGuardLvl, setMagicGuardLvl] = useState(0);

  const filtered = useMemo(() => {
    // Selecting an unverified skill (see classSkills.js) means there's no trustworthy
    // damage formula to compute anything from -- rather than guess, show nothing and
    // let the "not yet supported" banner elsewhere in the UI explain why.
    if (!dmg) return [];
    let list = MONSTER_DB.filter(m => {
      // Boss mobs are 1-spawn/long-respawn and aren't a viable grinding source, so
      // they're hidden by default -- toggling the chip flips to showing ONLY bosses,
      // rather than the usual "only"-filter semantics of the other Type chips.
      if (bossOnly ? !m.boss : m.boss) return false;
      // Heal can only ever damage undead monsters -- this isn't a togglable preference
      // like undeadOnly below, it's a hard game-mechanic constraint of the active skill.
      if (isHeal && !UNDEAD_IDS.has(m.id)) return false;
      if (undeadOnly && !UNDEAD_IDS.has(m.id)) return false;
      if (autoOnly && !m.auto) return false;
      if (hideUnknownLoc && m.location === "Location unknown") return false;
      // No map data at all (spawnMapsFor returns null -- neither Map.wz-verified nor
      // hand-curated) means an empty map-card list on the monster, which in practice
      // marks a monster whose crosswalk never resolved to anything trustworthy (see
      // the 17-monster "unresolved" set in monsterDb.js's header comment) -- these
      // carry a plausible-looking hand-typed `location` string (so hideUnknownLoc alone
      // doesn't catch them) but no verifiable spawn location at all.
      if (hideNoMapData && !spawnMapsFor(m.id)) return false;
      if (zoneFilter && !monsterZones(m).has(zoneFilter)) return false;
      if (weakFilter && m.weak !== weakFilter) return false;
      if (m.level < levelMin || m.level > levelMax) return false;
      if (query) {
        const q = query.toLowerCase();
        if (!m.name.toLowerCase().includes(q) && !m.location.toLowerCase().includes(q) &&
            !m.weak.toLowerCase().includes(q) && !m.strong.toLowerCase().includes(q)) return false;
      }
      return true;
    });
    list = list.map(m => {
      const isUndead = UNDEAD_IDS.has(m.id);
      // Elemental skills (Fire Arrow, Poison Breath, Cold Beam, Thunder Bolt) deal
      // different damage PER MONSTER depending on that monster's own weak/strong/
      // immune tags -- everything below this point uses mDmg (monster-adjusted), not
      // the character-only `dmg` used for the top panel's class-level badges.
      const mult = elementalMultiplier(activeSkill.element, m);
      const mDmg = activeSkill.element ? scaleDamage(dmg, mult) : dmg;
      // Each hit is rolled off the active skill's formula independently, so per-cast
      // min damage is hitsPerCast x a single hit's min (matches Magic Claw's 2
      // independently-rolled hits/cast; generalizes to any skill's own hit count).
      const immune = mult === 0;
      const hits = immune ? null : hitsToKill(m.hp, m.mDef, mDmg.min * activeSkill.hitsPerCast);
      // Heal's MP cost depends on healLvl (29 + healLvl), already folded into dmg.mpCost
      // by healDmg -- every other skill's cost is a flat per-character mpCost(CHAR).
      const mpCostPerCast = isHeal ? dmg.mpCost : (activeSkill.mpCost ? activeSkill.mpCost(CHAR) : 20);
      const mpReturn = mpEaterExpectedReturn(mpEaterLvl, m.mp, activeSkill.hitsPerCast);
      const netMp = netMpCost(mpCostPerCast, mpReturn);
      const anyProc = mpEaterAnyProcChance(mpEaterLvl, activeSkill.hitsPerCast);
      const mobIncomePerKill = incomePerKillFor(m.id);
      // Heal is a real fixed-radius AoE that can kill up to `healTargets` undead per
      // successful cast (see the Undead Hit/Cast slider) -- every other skill here is
      // still modeled as single-target-per-cast (Slash Blast/Somersault Kick's own
      // multi-mob AoE isn't throughput-modeled yet, same gap noted in classSkills.js).
      const killsPerCast = isHeal ? healTargets / (hits || 1) : 1;
      const netMpPerSessionUnit = isHeal ? netMp : netMp * hits;
      // Incoming damage / HP potions -- see the "Take Damage" toggle and
      // formulas.js's incomingDamagePerHit header comment. m.wAtk is this
      // monster's own physical attack stat (already in MONSTER_DB).
      const rawHpLossPerSec = takeDamage ? hpLossPerSecond(m.wAtk, CHAR.def, hitIntervalSec) : 0;
      // Magic Guard (Magician only, see the state declaration above) redirects
      // part of that HP-loss stream into an MP-loss stream instead.
      const magicGuardApplies = takeDamage && activeSkill.class === "magician" && magicGuardLvl > 0;
      const { hpLossPerSec, extraMpLossPerSec } = magicGuardApplies
        ? applyMagicGuard(rawHpLossPerSec, magicGuardLvl)
        : { hpLossPerSec: rawHpLossPerSec, extraMpLossPerSec: 0 };
      // Elemental immunity means this skill can never kill this monster -- session
      // profit is a flat zero rather than running sessionProfit with a null hits.
      const session = immune
        ? { casts: 0, kills: 0, potCost: 0, mpPotCost: 0, hpPotCost: 0, mpPotsNeeded: 0, hpPotsNeeded: 0, income: 0, profit: 0, totalExp: 0, levelsGained: 0, leftoverPct: charExpPct, finalLevel: CHAR.level }
        : sessionProfit(sessionMins, activeSkill.castTimeSec, killsPerCast, netMpPerSessionUnit, m.exp, CHAR.level, charExpPct, potionKey, CHAR.mpMax, mobIncomePerKill, hpLossPerSec, hpPotionKey, CHAR.hpMax, extraMpLossPerSec);
      // Efficiency ratio = actual casts needed to kill / total exp on offer -- lower is
      // better (fewer casts per unit of exp). Deliberately NOT hp/exp: with damage far
      // exceeding what's needed to kill a low-level mob, a tiny-hp/tiny-exp monster
      // could look artificially "efficient" on a pure hp-based ratio even though a
      // real, appropriately-leveled monster nets far more exp for the same 1 cast.
      const ratio = immune ? Infinity
        : isHeal ? hits / (m.exp * EXP_MULTI * Math.min(healTargets, 6)) : hits / (m.exp * EXP_MULTI);
      // EXP/hr: the same casts-to-kill-per-exp math as ratio above, just inverted and
      // scaled into an intuitive, higher-is-better unit for display -- "how much reward
      // am I actually getting" is a much clearer question than an abstract ratio number.
      const expPerHour = immune ? 0
        : isHeal ? (m.exp * EXP_MULTI * Math.min(healTargets, 6) / hits) * (3600 / activeSkill.castTimeSec)
        : (m.exp * EXP_MULTI / hits) * (3600 / activeSkill.castTimeSec);
      return {
        ...m,
        undead: isUndead,
        effHP: m.hp + m.mDef,
        ratio,
        primaryRatio: ratio,
        primaryExpPerHour: expPerHour,
        expPerHour,
        hits,
        elementalMult: mult,
        dmgMin: mDmg.min, dmgMax: mDmg.max,
        oneshotLvl: immune ? null : oneshotLevel(m.hp, m.mDef, CHAR, activeSkill.apDistribution, stats => scaleDamage(dmgFn(stats), mult), activeSkill.hitsPerCast),
        exp2x: m.exp * EXP_MULTI,
        mpCostPerCast,
        mcNetMp: netMp,
        mcAnyProc: anyProc,
        mcSession: session,
        incomePerKill: mobIncomePerKill,
        incomeIsEstimated: MOB_INCOME_PER_KILL[m.id] === undefined,
        spawnMaps: spawnMapsFor(m.id),
      };
    });
    // Efficiency tiers are percentile-based against the CURRENTLY visible list, not a
    // fixed number -- exp/hour is entirely character-level-dependent (a level 20 and a
    // level 60 character have completely different "good" absolute values against the
    // same monster set), so a fixed cutoff would misclassify constantly as level/gear
    // change. Top third of primaryExpPerHour = "high", middle third = "mid", rest = "low".
    const sortedRatios = list.map(m => m.primaryRatio).sort((a, b) => a - b);
    const effP33 = sortedRatios[Math.floor(sortedRatios.length / 3)];
    const effP66 = sortedRatios[Math.floor(sortedRatios.length * 2 / 3)];
    list = list.map(m => ({
      ...m,
      effTier: (effP33 === undefined) ? "mid" : m.primaryRatio <= effP33 ? "high" : m.primaryRatio <= effP66 ? "mid" : "low",
    }));
    // Second filter pass: efficiency/casts buckets need m.primaryRatio/m.hits, which
    // only exist after enrichment above.
    if (effFilter) {
      list = list.filter(m => m.effTier === effFilter);
    }
    if (castsFilter) {
      list = list.filter(m => m.hits >= castsFilter[0] && m.hits <= castsFilter[1]);
    }
    // Hide monsters with no viable spawn location: every known map is rope-heavy /
    // low-spawn, not just some of them (a monster with even one decent map is fine).
    // Monsters with no resolved spawn maps at all aren't touched by either filter.
    if (hideRopeHeavy) {
      list = list.filter(m => !m.spawnMaps || !m.spawnMaps.length || !m.spawnMaps.every(s => isRopeHeavyMap(s.mapId)));
    }
    if (hideLowSpawn) {
      list = list.filter(m => !m.spawnMaps || !m.spawnMaps.length || !m.spawnMaps.every(s => isLowSpawnMap(s.mapId)));
    }
    if (hideUnreachable) {
      list = list.filter(m => !m.spawnMaps || !m.spawnMaps.length || !m.spawnMaps.every(s => isUnreachableMap(s.mapId)));
    }
    // Map-quality score threshold: hide a monster only if EVERY known spawn map's
    // score for the ACTIVE skill's own hitbox archetype (see classSkills.js's
    // mapScoreArchetype/SCORE_FIELD) falls below the chosen minimum (1-5). Heal
    // (archetype "vertical") automatically only ever sees undead monsters here --
    // the isHeal filter earlier already restricts the whole list to undead.
    if (minMapScore > 0) {
      const scoreField = SCORE_FIELD[activeSkill.mapScoreArchetype];
      list = list.filter(m => !m.spawnMaps || !m.spawnMaps.length ||
        !m.spawnMaps.every(s => MAP_SCORES[s.mapId] && MAP_SCORES[s.mapId][scoreField] < minMapScore));
    }
    if (sortBy === "efficiency") list.sort((a,b) => sortDir*(a.primaryRatio - b.primaryRatio));
    else if (sortBy === "level") list.sort((a,b) => sortDir*(a.level - b.level));
    else if (sortBy === "exp") list.sort((a,b) => sortDir*(a.exp2x - b.exp2x));
    else if (sortBy === "hp") list.sort((a,b) => sortDir*(a.hp - b.hp));
    return list;
  }, [query, levelMin, levelMax, bossOnly, undeadOnly, autoOnly, hideUnknownLoc, hideNoMapData, hideRopeHeavy, hideLowSpawn, hideUnreachable, minMapScore, weakFilter, effFilter, castsFilter, zoneFilter, sortBy, sortDir, isHeal, healTargets, mpEaterLvl, sessionMins, potionKey, takeDamage, hitIntervalSec, hpPotionKey, magicGuardLvl, CHAR, dmg, dmgFn, activeSkill]);

  return (
    <div style={{ minHeight:"100vh", background:"#0d1117", fontFamily:"monospace", color:"#e2e8f0" }}>
      {/* Header */}
      <div style={{ background:"linear-gradient(180deg,#1a0a2e,#0d1117)", borderBottom:"2px solid #7c3aed", padding:"16px 20px 12px" }}>
        <div style={{ maxWidth:900, margin:"0 auto" }}>
          <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:8 }}>
            <span style={{ fontSize:24 }}>[Shroom]</span>
            <div>
              <div style={{ fontSize:18, fontWeight:700, color:"#a78bfa", letterSpacing:1 }}>MAPLESTORY MONSTER DB</div>
              <div style={{ fontSize:10, color:"#6b7280", letterSpacing:2 }}>
                {MONSTER_DB.length} MONSTERS x {STAT_VERIFIED_IDS.size}/{MONSTER_DB.length} STAT-VERIFIED x {Object.keys(MAP_SCORES).length} MAPS SCORED x {Object.keys(REAL_SPAWNS).length} MAP.WZ-VERIFIED SPAWNS
              </div>
            </div>
          </div>
        </div>
      </div>

      <div style={{ maxWidth:900, margin:"0 auto", padding:"16px 12px" }}>

        {/* Class / Skill selector -- drives AP distribution, damage formula, cast time,
            and hits/targets-per-cast for everything below. See src/lib/classSkills.js:
            only skills with a sourced + spot-checked formula are selectable.
            classFilter (below) narrows the skill row to one class at a time, purely a
            display filter -- it never touches activeSkillKey by itself, so filtering
            to a different class doesn't silently swap which skill is actually active. */}
        <div style={{ marginBottom:12, padding:"10px 14px", border:"1px solid #30363d", borderRadius:8, background:"#161b22" }}>
          <div style={{ fontSize:10, color:"#6b7280", letterSpacing:1, marginBottom:6 }}>CLASS</div>
          <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:10 }}>
            <button onClick={() => setClassFilter(null)}
              style={{
                background: classFilter === null ? "#7c3aed22" : "#0d1117",
                border: `1px solid ${classFilter === null ? "#7c3aed" : "#30363d"}`,
                borderRadius:4, padding:"3px 10px",
                color: classFilter === null ? "#a78bfa" : "#9ca3af",
                fontFamily:"inherit", fontSize:11, fontWeight: classFilter === null ? 700 : 400, cursor:"pointer",
              }}>
              Show All Skills
            </button>
            {CLASS_LIST.map(cls => (
              <button key={cls} onClick={() => setClassFilter(cls)}
                style={{
                  background: classFilter === cls ? "#7c3aed22" : "#0d1117",
                  border: `1px solid ${classFilter === cls ? "#7c3aed" : "#30363d"}`,
                  borderRadius:4, padding:"3px 10px",
                  color: classFilter === cls ? "#a78bfa" : "#9ca3af",
                  fontFamily:"inherit", fontSize:11, fontWeight: classFilter === cls ? 700 : 400, cursor:"pointer",
                }}>
                {CLASS_LABEL[cls]}
              </button>
            ))}
          </div>
          <div style={{ fontSize:10, color:"#6b7280", letterSpacing:1, marginBottom:6 }}>PRIMARY SKILL</div>
          <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
            {SKILL_LIST.filter(s => classFilter === null || s.class === classFilter).map(s => (
              <button key={s.key}
                onClick={() => s.verified && setActiveSkillKey(s.key)}
                disabled={!s.verified}
                title={
                  !s.verified ? `${s.label} (${s.job}) -- not yet supported: ${s.notes}`
                  : s.notes ? `${s.label} -- ${s.job} -- ${s.notes}`
                  : `${s.label} -- ${s.job}`
                }
                style={{
                  background: activeSkillKey === s.key ? "#7c3aed22" : "#0d1117",
                  border: `1px solid ${activeSkillKey === s.key ? "#7c3aed" : "#30363d"}`,
                  borderRadius:4, padding:"3px 10px",
                  color: !s.verified ? "#4b5563" : activeSkillKey === s.key ? "#a78bfa" : "#9ca3af",
                  fontFamily:"inherit", fontSize:11, fontWeight: activeSkillKey === s.key ? 700 : 400,
                  cursor: s.verified ? "pointer" : "not-allowed",
                }}>
                {s.label}{!s.verified ? " [soon]" : ""}
              </button>
            ))}
          </div>
          {!activeSkill.verified && (
            <div style={{ marginTop:8, fontSize:11, color:"#f87171" }}>
              {activeSkill.label} has no verified damage formula yet -- {activeSkill.notes}
            </div>
          )}
          {isHeal && healLvl === 0 && (
            <div style={{ marginTop:8, fontSize:11, color:"#eab308" }}>
              Set Heal's skill level below to see monsters -- Heal only damages undead, and needs a level to compute its own damage.
            </div>
          )}
        </div>

        {/* Character Panel */}
        <div style={{ marginBottom:12, border:"1px solid #30363d", borderRadius:8, overflow:"hidden" }}>
          <button onClick={()=>setCharPanelOpen(o=>!o)}
            style={{ width:"100%", background:"#161b22", border:"none", padding:"10px 14px", color:"#e2e8f0", fontFamily:"monospace", fontSize:12, cursor:"pointer", display:"flex", justifyContent:"space-between", alignItems:"center", flexWrap:"wrap", gap:8, textAlign:"left" }}>
            <span style={{ fontWeight:700, letterSpacing:1, color:"#a78bfa" }}>CHARACTER Lv{CHAR.level} {charPanelOpen ? "[close]" : "[edit]"}</span>
            <span style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
              {badge(activeSkill.apDistribution.primaryStat.toUpperCase(), CHAR[activeSkill.apDistribution.primaryStat], "#6366f1")}
              {badge("W.ATT", CHAR.weaponAtk, "#8b5cf6")}
              {dmg && badge("MIN/HIT", dmg.min.toFixed(0), "#14532d", "#86efac")}
              {dmg && badge("MAX/HIT", dmg.max.toFixed(0), "#14532d", "#4ade80")}
              {badge("MP", CHAR.mpMax, "#0369a1")}
              {badge("EXP", `${charExpPct.toFixed(2)}%`, "#facc15")}
            </span>
          </button>
          {charPanelOpen && (
            <div style={{ background:"#0d1117", padding:"12px 14px", display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:"10px 16px" }}>
              {[
                ["Level", charLevel, setCharLevel, 1, 70, 1],
                ["STR", charStr, setCharStr, 4, 999, 1],
                ["DEX", charDex, setCharDex, 4, 999, 1],
                ["INT", charInt, setCharInt, 10, 999, 1],
                ["LUK", charLuk, setCharLuk, 4, 999, 1],
                ["Weapon Attack", charWeaponAtk, setCharWeaponAtk, 0, 200, 1],
                ["Max MP", charMpMax, setCharMpMax, 100, 30000, 10],
                ["Max HP", charHpMax, setCharHpMax, 100, 30000, 10],
                ["Defense", charDef, setCharDef, 0, 999, 1],
                ["Current EXP %", charExpPct, setCharExpPct, 0, 99.99, 0.01],
              ].map(([label, val, setter, min, max, step]) => (
                <div key={label}>
                  <div style={{ fontSize:10, color:"#6b7280", marginBottom:3, letterSpacing:1 }}>{label.toUpperCase()}</div>
                  <input type="number" value={val} min={min} max={max} step={step}
                    onChange={e => setter(step < 1 ? parseFloat(e.target.value)||0 : parseInt(e.target.value)||0)}
                    style={{ width:"100%", background:"#161b22", border:"1px solid #30363d", borderRadius:4, padding:"4px 8px", color:"#e2e8f0", fontFamily:"monospace", fontSize:12, boxSizing:"border-box" }} />
                </div>
              ))}
              <div style={{ gridColumn:"1/-1", display:"flex", alignItems:"center", gap:12, flexWrap:"wrap" }}>
                <button onClick={() => {
                  setCharLevel(DEFAULT_CHAR.level); setCharStr(DEFAULT_CHAR.str); setCharDex(DEFAULT_CHAR.dex);
                  setCharInt(DEFAULT_CHAR.int); setCharLuk(DEFAULT_CHAR.luk); setCharWeaponAtk(DEFAULT_CHAR.weaponAtk);
                  setCharMpMax(DEFAULT_CHAR.mpMax); setCharHpMax(DEFAULT_CHAR.hpMax); setCharDef(DEFAULT_CHAR.def);
                  setCharExpPct(DEFAULT_CHAR.expPct);
                }} style={{ background:"#21262d", border:"1px solid #30363d", borderRadius:4, padding:"4px 12px", color:"#9ca3af", fontFamily:"monospace", fontSize:11, cursor:"pointer" }}>
                  Reset to defaults
                </button>
                <span style={{ fontSize:10, color:"#4b5563" }}>
                  Projections assume +{activeSkill.apDistribution.primaryPerLevel} {activeSkill.apDistribution.primaryStat.toUpperCase()} / +{activeSkill.apDistribution.secondaryPerLevel} {activeSkill.apDistribution.secondaryStat.toUpperCase()} per level-up ({activeSkill.label})
                </span>
              </div>
            </div>
          )}
        </div>

        {/* Controls */}
        <div style={{ display:"flex", gap:8, flexWrap:"wrap", marginBottom:12 }}>
          <input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search name, location, element..."
            style={{ flex:1, minWidth:180, background:"#161b22", border:"1px solid #30363d", borderRadius:6, padding:"8px 12px", color:"#e2e8f0", fontFamily:"inherit", fontSize:12 }} />
          <input type="number" value={levelMin} onChange={e=>setLevelMin(+e.target.value)} placeholder="Min Lv"
            style={{ width:70, background:"#161b22", border:"1px solid #30363d", borderRadius:6, padding:"8px", color:"#e2e8f0", fontFamily:"inherit", fontSize:12, textAlign:"center" }} />
          <span style={{ lineHeight:"34px", color:"#6b7280" }}>-</span>
          <input type="number" value={levelMax} onChange={e=>setLevelMax(+e.target.value)} placeholder="Max Lv"
            style={{ width:70, background:"#161b22", border:"1px solid #30363d", borderRadius:6, padding:"8px", color:"#e2e8f0", fontFamily:"inherit", fontSize:12, textAlign:"center" }} />
          <select value={sortBy} onChange={e=>setSortBy(e.target.value)}
            style={{ background:"#161b22", border:"1px solid #30363d", borderRadius:6, padding:"8px", color:"#e2e8f0", fontFamily:"inherit", fontSize:12 }}>
            <option value="efficiency">Sort: Efficiency</option>
            <option value="level">Sort: Level</option>
            <option value="exp">Sort: EXP</option>
            <option value="hp">Sort: HP</option>
          </select>
          <button onClick={()=>setSortDir(d=>-d)}
            title={sortDir===1 ? "Ascending (lowest first) -- click for descending" : "Descending (highest first) -- click for ascending"}
            style={{ background:"#161b22", border:"1px solid #30363d", borderRadius:6, padding:"8px 12px", color:"#e2e8f0", fontFamily:"inherit", fontSize:12, cursor:"pointer", display:"flex", alignItems:"center", gap:4 }}>
            {sortDir===1 ? "^ Asc" : "v Desc"}
          </button>
        </div>

        {/* General controls -- apply to whichever skill is active, not Heal-specific */}
        <div style={{ display:"flex", flexDirection:"column", gap:8, marginBottom:12, padding:"10px 12px", background:"#161b22", border:"1px solid #21262d", borderRadius:6 }}>
          <FilterRow label="MP Eater Lv">
            <input type="range" min={0} max={20} value={mpEaterLvl} onChange={e=>setMpEaterLvl(+e.target.value)}
              style={{ width:80, accentColor:"#60a5fa" }} />
            <span style={{ color:"#60a5fa", fontWeight:700, minWidth:20 }}>{mpEaterLvl}</span>
            <span style={{ color:"#4b5563", fontSize:11 }}>
              {mpEaterLvl===0 ? "(disabled)" : `(${mpEaterLvl}% chance, absorb ${(mpEaterLvl/2).toFixed(1)}% mob MP)`}
            </span>
          </FilterRow>
          <FilterRow label="Session">
            <input type="range" min={10} max={180} step={10} value={sessionMins} onChange={e=>setSessionMins(+e.target.value)}
              style={{ width:100, accentColor:"#f59e0b" }} />
            <span style={{ color:"#f59e0b", fontWeight:700, minWidth:30 }}>{sessionMins}m</span>
          </FilterRow>
          <FilterRow label="Potion">
            <select value={potionKey} onChange={e=>setPotionKey(e.target.value)}
              style={{ background:"#0d1117", color:"#e5e7eb", border:"1px solid #21262d", borderRadius:4, fontSize:11, padding:"2px 4px" }}>
              {Object.entries(POTIONS).map(([key, p]) => (
                <option key={key} value={key}>{p.label}</option>
              ))}
            </select>
          </FilterRow>
          <FilterRow label="Take Damage" hint='Models incoming damage from the monster and the HP potions needed to sustain it -- roughly one hit every "Hit Interval" seconds for max(1, monster W.ATK - your Defense) each time. Warriors are melee and always in range for this; other classes only take it if you expect to be mobbed/pulling AoE packs. Turn off to model taking no damage at all.'>
            <button onClick={()=>setTakeDamage(t=>!t)}
              style={{ background: takeDamage ? "#7c3aed22" : "#161b22", border:`1px solid ${takeDamage ? "#7c3aed" : "#30363d"}`, borderRadius:4, padding:"3px 10px", color: takeDamage ? "#a78bfa" : "#6b7280", fontFamily:"inherit", fontSize:11, fontWeight:700, cursor:"pointer" }}>
              {takeDamage ? "ON" : "OFF"}
            </button>
            {takeDamage && (
              <>
                <span style={{ fontSize:10, color:"#6b7280", marginLeft:8 }}>Hit Interval</span>
                <input type="range" min={3} max={5} step={0.5} value={hitIntervalSec} onChange={e=>setHitIntervalSec(+e.target.value)}
                  style={{ width:70, accentColor:"#f87171" }} />
                <span style={{ color:"#f87171", fontWeight:700, minWidth:26 }}>{hitIntervalSec}s</span>
                <select value={hpPotionKey} onChange={e=>setHpPotionKey(e.target.value)}
                  style={{ background:"#0d1117", color:"#e5e7eb", border:"1px solid #21262d", borderRadius:4, fontSize:11, padding:"2px 4px", marginLeft:8 }}>
                  {Object.entries(HP_POTIONS).map(([key, p]) => (
                    <option key={key} value={key} style={isSuspiciousPotionPrice(p, "hp") ? { color:"#f59e0b" } : undefined}>
                      {p.label}{isSuspiciousPotionPrice(p, "hp") ? " (price unverified)" : ""}
                    </option>
                  ))}
                </select>
              </>
            )}
          </FilterRow>
          {takeDamage && activeSkill.class === "magician" && (
            <FilterRow label="Magic Guard" hint="Converts a % of incoming damage into MP loss instead of HP loss while active (v62 Skill.wz id 2001003, Magician 1st job) -- 2% per level, capping at 40% at Lv20. Also adds its own small MP cost to recast the buff periodically. Reduces HP pot usage, increases MP pot usage.">
              <input type="range" min={0} max={20} value={magicGuardLvl} onChange={e=>setMagicGuardLvl(+e.target.value)}
                style={{ width:80, accentColor:"#60a5fa" }} />
              <span style={{ color:"#60a5fa", fontWeight:700, minWidth:20 }}>{magicGuardLvl}</span>
              <span style={{ fontSize:10, color:"#4b5563" }}>
                {magicGuardLvl === 0 ? "(disabled)" : `(${magicGuardPct(magicGuardLvl)}% dmg -> MP)`}
              </span>
            </FilterRow>
          )}
        </div>

        {/* Heal-only controls -- only meaningful, and only shown, when Heal is the active skill */}
        {isHeal && (
          <div style={{ display:"flex", flexDirection:"column", gap:8, marginBottom:12, padding:"10px 12px", background:"#161b22", border:"1px solid #21262d", borderRadius:6 }}>
            <span style={{ fontSize:11, color:"#86efac", fontWeight:700, letterSpacing:1 }}>+ HEAL</span>
            <FilterRow label="Skill Lv">
              <input type="range" min={0} max={30} value={healLvl} onChange={e=>setHealLvl(+e.target.value)}
                style={{ width:100, accentColor:"#86efac" }} />
              <span style={{ color:"#86efac", fontWeight:700, minWidth:20 }}>{healLvl}</span>
              <span style={{ color:"#4b5563", fontSize:11 }}>({healLvl===0?"disabled":`${healLvl*15}% x ${29+healLvl} MP`})</span>
            </FilterRow>
            <FilterRow label="Undead Hit / Cast" hint='How many undead a single Heal cast kills -- affects kill throughput (exp/kills per cast, MP Eater proc rolls) only. Per-target Heal damage itself is fixed at a 6.5x multiplier (solo play, no party) -- see the "Heal dmg vs undead" line below.'>
              <input type="range" min={1} max={6} value={healTargets} onChange={e=>setHealTargets(+e.target.value)}
                style={{ width:80, accentColor:"#86efac" }} />
              <span style={{ color:"#86efac", fontWeight:700 }}>{healTargets}</span>
            </FilterRow>
            {healLvl > 0 && (
              <div style={{ fontSize:11, color:"#4b5563" }}>
                Heal dmg vs undead: <span style={{ color:"#86efac" }}>{healDmg(healLvl, CHAR.int, CHAR.luk, CHAR.weaponAtk).min.toFixed(0)}</span>-<span style={{ color:"#86efac" }}>{healDmg(healLvl, CHAR.int, CHAR.luk, CHAR.weaponAtk).max.toFixed(0)}</span> per target
              </div>
            )}
          </div>
        )}

        {/* Quick filters -- grouped by category, each its own labeled row */}
        <div style={{ display:"flex", flexDirection:"column", gap:8, marginBottom:16 }}>
          <FilterRow label="Level Range">
            {[["My range",17,25],["Low",1,15],["Mid",20,35],["High",35,60],["All",1,100]].map(([l,mn,mx])=>(
              <button key={l} onClick={()=>{setLevelMin(mn);setLevelMax(mx);}}
                style={{ background:"#161b22", border:`1px solid ${levelMin===mn&&levelMax===mx?"#7c3aed":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:levelMin===mn&&levelMax===mx?"#a78bfa":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer" }}>
                {l}
              </button>
            ))}
          </FilterRow>

          <FilterRow label="Zone" hint="Matches if ANY of the monster's known spawn maps falls in that zone (Maple Island, Victoria Island, Ossyria, Ludibrium, Mu Lung, Masteria, Haunted House)">
            {ZONE_NAMES.map(z => (
              <button key={z} onClick={()=>setZoneFilter(f=>f===z?null:z)}
                style={{ background:"#161b22", border:`1px solid ${zoneFilter===z?"#7c3aed":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:zoneFilter===z?"#a78bfa":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:zoneFilter===z?700:400 }}>
                {z}
              </button>
            ))}
          </FilterRow>

          <FilterRow label="Elemental Weakness">
            {[["Lightning","Lightning"],["Holy","Holy"],["Fire","Fire"]].map(([l,w])=>(
              <button key={l} onClick={()=>setWeakFilter(f=>f===w?null:w)}
                style={{ background:"#161b22", border:`1px solid ${weakFilter===w?"#7c3aed":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:weakFilter===w?"#a78bfa":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:weakFilter===w?700:400 }}>
                {l}
              </button>
            ))}
          </FilterRow>

          <FilterRow label="Efficiency" hint="EXP/HR tier relative to what's currently shown -- High = top third, Mid = middle third, Low = bottom third. Recalculates as you change level range/filters/character stats.">
            {[["Low","low"],["Mid","mid"],["High","high"]].map(([l,v])=>(
              <button key={l} onClick={()=>setEffFilter(f=>f===v?null:v)}
                style={{ background:"#161b22", border:`1px solid ${effFilter===v?"#7c3aed":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:effFilter===v?"#a78bfa":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:effFilter===v?700:400 }}>
                {l}
              </button>
            ))}
          </FilterRow>

          <FilterRow label="Casts" hint="Magic Claw casts to kill -- high efficiency is no good if it takes 40 casts">
            {[["OHKO",[1,1]],["2",[2,2]],["3",[3,3]],["4-10",[4,10]]].map(([l,range])=>(
              <button key={l} onClick={()=>setCastsFilter(f=>(f && f[0]===range[0] && f[1]===range[1]) ? null : range)}
                style={{ background:"#161b22", border:`1px solid ${castsFilter&&castsFilter[0]===range[0]&&castsFilter[1]===range[1]?"#7c3aed":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:castsFilter&&castsFilter[0]===range[0]&&castsFilter[1]===range[1]?"#a78bfa":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:castsFilter&&castsFilter[0]===range[0]&&castsFilter[1]===range[1]?700:400 }}>
                {l}
              </button>
            ))}
          </FilterRow>

          <FilterRow label="Type">
            <button onClick={()=>setBossOnly(v=>!v)}
              title="Bosses are hidden by default (1-spawn/long-respawn, not viable for long grinding sessions) -- toggle to show ONLY bosses instead"
              style={{ background:"#161b22", border:`1px solid ${bossOnly?"#7f1d1d":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:bossOnly?"#fca5a5":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:bossOnly?700:400 }}>
              {bossOnly ? "Boss Only" : "Hiding Boss"}
            </button>
            <button onClick={()=>setUndeadOnly(v=>!v)}
              style={{ background:"#161b22", border:`1px solid ${undeadOnly?"#14532d":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:undeadOnly?"#86efac":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:undeadOnly?700:400 }}>
              + Undead
            </button>
            <button onClick={()=>setAutoOnly(v=>!v)}
              style={{ background:"#161b22", border:`1px solid ${autoOnly?"#3f2d0d":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:autoOnly?"#fbbf24":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:autoOnly?700:400 }}>
              Normal
            </button>
            <button onClick={()=>setHideUnknownLoc(v=>!v)}
              title="Monsters with no resolved spawn location are hidden by default -- mostly event/unused mobs pulled in from the Cosmic v83 dump, not real farmable content"
              style={{ background:"#161b22", border:`1px solid ${hideUnknownLoc?"#374151":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:hideUnknownLoc?"#d1d5db":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:hideUnknownLoc?700:400 }}>
              {hideUnknownLoc ? "Hiding Unknown Loc." : "Show Unknown Loc."}
            </button>
            <button onClick={()=>setHideNoMapData(v=>!v)}
              title="Monsters with no spawn map data at all -- neither Map.wz-verified nor hand-curated -- are hidden by default (e.g. Jr. Necki (Strong), Ligator, Sporewood): the crosswalk never resolved these to anything trustworthy, despite a plausible-looking location label"
              style={{ background:"#161b22", border:`1px solid ${hideNoMapData?"#374151":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:hideNoMapData?"#d1d5db":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:hideNoMapData?700:400 }}>
              {hideNoMapData ? "Hiding No-Map Mobs" : "Show No-Map Mobs"}
            </button>
            <button onClick={()=>setHideRopeHeavy(v=>!v)}
              title="Hides monsters whose EVERY known spawn map is rope/ladder-heavy (see the ROPE-HEAVY map badge) -- a monster with at least one non-rope-heavy map stays visible"
              style={{ background:"#161b22", border:`1px solid ${hideRopeHeavy?"#5c3315":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:hideRopeHeavy?"#f59e0b":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:hideRopeHeavy?700:400 }}>
              {hideRopeHeavy ? "Hiding Rope-Heavy Maps" : "Show Rope-Heavy Maps"}
            </button>
            <button onClick={()=>setHideLowSpawn(v=>!v)}
              title="Hides monsters whose EVERY known spawn map has a low total mob population (see the LOW SPAWN map badge) -- likely to be cleared faster than it respawns, leaving you idle. A monster with at least one well-stocked map stays visible"
              style={{ background:"#161b22", border:`1px solid ${hideLowSpawn?"#5c1a1a":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:hideLowSpawn?"#f87171":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:hideLowSpawn?700:400 }}>
              {hideLowSpawn ? "Hiding Low-Spawn Maps" : "Show Low-Spawn Maps"}
            </button>
            <button onClick={()=>setHideUnreachable(v=>!v)}
              title="Hides monsters whose EVERY known spawn map has no confirmed portal path from a town (see the NO PORTAL PATH map badge). Caveat: this only follows walkable portals -- Party Quests and some event maps are entered via NPC dialogue and will show as unreachable even though they're real content. A monster with at least one confirmed-reachable map stays visible"
              style={{ background:"#161b22", border:`1px solid ${hideUnreachable?"#3d1f5c":"#30363d"}`, borderRadius:4, padding:"3px 10px", color:hideUnreachable?"#c4b5fd":"#9ca3af", fontFamily:"inherit", fontSize:11, cursor:"pointer", fontWeight:hideUnreachable?700:400 }}>
              {hideUnreachable ? "Hiding No-Portal-Path Maps" : "Show No-Portal-Path Maps"}
            </button>
          </FilterRow>

          <FilterRow label="Min Map Score" hint={`Hides a monster only if EVERY known spawn map scores below this (1=red/worst - 5=green/best, 0=off) for ${activeSkill.label}'s own hitbox archetype (${SCORE_LABEL[activeSkill.mapScoreArchetype]} -- see classSkills.js mapScoreArchetype).`}>
            <span style={{ fontSize:10, color:"#6b7280" }}>{SCORE_LABEL[activeSkill.mapScoreArchetype]}</span>
            <select value={minMapScore} onChange={e=>setMinMapScore(+e.target.value)}
              style={{
                background:"#161b22",
                border:`1px solid ${minMapScore > 0 ? scoreColor(minMapScore) : "#30363d"}`,
                borderRadius:4, color: minMapScore > 0 ? scoreColor(minMapScore) : "#e2e8f0",
                fontFamily:"inherit", fontSize:11, fontWeight: minMapScore > 0 ? 700 : 400, padding:"2px 4px",
              }}>
              <option value={0} style={{ color:"#9ca3af", background:"#161b22" }}>off</option>
              {[1,2,3,4,5].map(n => (
                <option key={n} value={n} style={{ color:scoreColor(n), background:"#161b22", fontWeight:700 }}>
                  {n}+ {n===1?"(red/worst)":n===5?"(green/best)":""}
                </option>
              ))}
            </select>
          </FilterRow>

          {(query || weakFilter || effFilter || castsFilter || zoneFilter) && (
            <div>
              <button onClick={()=>{setQuery("");setWeakFilter(null);setEffFilter(null);setCastsFilter(null);setZoneFilter(null);}}
                style={{ background:"#7c3aed22", border:"1px solid #7c3aed", borderRadius:4, padding:"3px 10px", color:"#a78bfa", fontFamily:"inherit", fontSize:11, cursor:"pointer" }}>
                x Clear filters
              </button>
            </div>
          )}
        </div>

        <div style={{ fontSize:11, color:"#4b5563", marginBottom:10, letterSpacing:1 }}>
          {filtered.length} MONSTER{filtered.length!==1?"S":""} x EXP/HR = (EXP x 2 / CASTS TO KILL) x 3600/CAST-TIME x HIGHER = BETTER
        </div>

        {/* Monster list */}
        <div style={{ display:"grid", gap:8 }}>
        {/* Monster list -- virtualized: only visibly-nearby cards are actually
            mounted, since each card can include several real spawn-map images */}
        <VirtualList
          items={filtered}
          estimatedItemHeight={190}
          overscan={6}
          renderItem={(m, i) => (
            <MonsterCard key={m.id} m={m} i={i} selected={selected} setSelected={setSelected}
              setWorldMapMapId={setWorldMapMapId} CHAR={CHAR} dmg={dmg} activeSkill={activeSkill} isHeal={isHeal}
              healTargets={healTargets} mpEaterLvl={mpEaterLvl} sessionMins={sessionMins} potionKey={potionKey} />
          )}
        />
        </div>

        {filtered.length === 0 && (
          <div style={{ textAlign:"center", padding:"40px 0", color:"#6b7280", fontSize:13 }}>
            {!activeSkill.verified
              ? `${activeSkill.label} has no verified damage formula yet, so there's nothing to rank. Pick a verified skill above to see monsters.`
              : isHeal && healLvl === 0
              ? "Set Heal's skill level below to see monsters."
              : "No monsters match your filters."}
          </div>
        )}

        <div style={{ marginTop:24, fontSize:10, color:"#374151", textAlign:"center", lineHeight:1.8 }}>
          SOURCE: MEOWDB.COM/MSCLASSIC + LEGENDS.ML/LIB/MONSTER x {MONSTER_DB.length} MONSTERS INDEXED<br/>
          SPAWN MAPS: {Object.keys(REAL_SPAWNS).length}/{MONSTER_DB.length} MONSTERS MAP.WZ-VERIFIED, REST ARE CURATED/UNVERIFIED<br/>
          STATS: {STAT_VERIFIED_IDS.size}/{MONSTER_DB.length} MONSTERS VERIFIED VS MAPLELEGENDS -- 105 CURATED VIA INDIVIDUAL LEGENDS.ML + COSMIC V83 CROSSWALK, REST VIA A DIVERSE SPOT-CHECK OF THE SAME-SOURCE COSMIC V83 IMPORT<br/>
          {MONSTER_DB.length - STAT_VERIFIED_IDS.size} MONSTERS (NORMAL) NOT YET VERIFIED<br/>
          MAP SCORES: DERIVED FROM MAP.WZ FOOTHOLD + MOB-SPAWN GEOMETRY x {Object.keys(MAP_SCORES).length} MAPS SCORED<br/>
          EXP/HR = (EXP x 2 / CASTS TO KILL) x 3600/CAST-TIME, WHERE CASTS TO KILL USES YOUR ACTUAL DAMAGE x DAMAGE FORMULA: V62 MAGIC CLAW
        </div>
      </div>

      {worldMapMapId !== null && (
        <MapExpandModal key={worldMapMapId} mapId={worldMapMapId} onClose={()=>setWorldMapMapId(null)} />
      )}
    </div>
  );
}

// -- Expanded map view: local minimap thumbnail + world map with a marker at this
// map's location, shown side by side. Falls back gracefully to thumbnail-only if
// this map has no resolved world-map spot (e.g. a handful of Maple Island tutorial
// maps whose regional world-map image wasn't included in the WorldMap.wz extract).
function MapExpandModal({ mapId, onClose }) {
  // currentMapId lets portal markers navigate within the modal without closing it;
  // mapHistory is a simple back-stack of previously-viewed maps in this session.
  // Pass key={mapId} where this is rendered so opening it for a different mapId
  // (even without an intervening close) resets both to the fresh target.
  const [currentMapId, setCurrentMapId] = useState(mapId);
  const [mapHistory, setMapHistory] = useState([]);
  const navigateTo = targetMapId => {
    setMapHistory(h => [...h, currentMapId]);
    setCurrentMapId(targetMapId);
    setShowSpawns(false);
    setShowRopes(false);
    setShowPortals(false);
  };
  const goBack = () => {
    setMapHistory(h => {
      if (!h.length) return h;
      setCurrentMapId(h[h.length - 1]);
      return h.slice(0, -1);
    });
  };

  const spotInfo = WORLD_MAP_DATA.spots[currentMapId];
  const region = spotInfo ? WORLD_MAP_DATA.regions[spotInfo.region] : null;
  const worldImg = spotInfo && `data/worldmaps/${spotInfo.region}.png`;
  const mapNameFull = (typeof MAP_NAMES !== "undefined" && MAP_NAMES[currentMapId]) || null;
  const spawnInfo = (typeof MAP_MOB_SPAWNS !== "undefined" && MAP_MOB_SPAWNS[currentMapId]) || null;
  const ropeSegs = (typeof MAP_ROPES !== "undefined" && MAP_ROPES[currentMapId]) || null;
  const portalInfo = (typeof MAP_PORTALS !== "undefined" && MAP_PORTALS[currentMapId]) || null;
  const [showSpawns, setShowSpawns] = useState(false);
  const [showRopes, setShowRopes] = useState(false);
  const [showPortals, setShowPortals] = useState(false);

  return (
    <div onClick={onClose} style={{ position:"fixed", inset:0, background:"#000000cc", zIndex:1000, display:"flex", alignItems:"center", justifyContent:"center", padding:20 }}>
      <div onClick={e=>e.stopPropagation()} style={{ background:"#161b22", border:"1px solid #30363d", borderRadius:8, padding:16, maxWidth:900, width:"100%", maxHeight:"90vh", overflow:"auto" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:12 }}>
          <div>
            {/* Styled like the in-game minimap's map-name bar: "Street : Map Name" */}
            <div style={{ color:"#e2e8f0", fontWeight:700, fontSize:14 }}>
              {mapNameFull || `Map #${currentMapId}`}
            </div>
            <div style={{ color:"#6b7280", fontSize:10, letterSpacing:1, marginTop:2 }}>MAP #{currentMapId}</div>
          </div>
          <div style={{ display:"flex", gap:6 }}>
            {mapHistory.length > 0 && (
              <button onClick={goBack} style={{ background:"#21262d", border:"1px solid #30363d", borderRadius:4, color:"#e2e8f0", fontFamily:"inherit", fontSize:12, padding:"4px 10px", cursor:"pointer" }}>
                [&lt;] Back
              </button>
            )}
            <button onClick={onClose} style={{ background:"#21262d", border:"1px solid #30363d", borderRadius:4, color:"#e2e8f0", fontFamily:"inherit", fontSize:12, padding:"4px 10px", cursor:"pointer" }}>
              [x] Close
            </button>
          </div>
        </div>
        <div style={{ display:"flex", gap:16, flexWrap:"wrap" }}>
          <div style={{ flex:"1 1 260px" }}>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:6 }}>
              <div style={{ fontSize:10, color:"#6b7280", letterSpacing:1 }}>MINIMAP</div>
              {spawnInfo && (
                <button
                  onClick={()=>setShowSpawns(v=>!v)}
                  style={{
                    background: showSpawns ? "#ef444422" : "#21262d",
                    border: `1px solid ${showSpawns ? "#ef4444" : "#30363d"}`,
                    borderRadius:999, color: showSpawns ? "#ef4444" : "#9ca3af",
                    fontFamily:"inherit", fontSize:10, fontWeight:700,
                    padding:"2px 9px", cursor:"pointer", letterSpacing:0.5,
                  }}
                  title={`${spawnInfo.s.length} mob spawn point${spawnInfo.s.length===1?"":"s"} (Map.wz life data)`}
                >
                  ● Mob Spawns
                </button>
              )}
              {ropeSegs && spawnInfo && (
                <button
                  onClick={()=>setShowRopes(v=>!v)}
                  style={{
                    background: showRopes ? "#f59e0b22" : "#21262d",
                    border: `1px solid ${showRopes ? "#f59e0b" : "#30363d"}`,
                    borderRadius:999, color: showRopes ? "#f59e0b" : "#9ca3af",
                    fontFamily:"inherit", fontSize:10, fontWeight:700,
                    padding:"2px 9px", cursor:"pointer", letterSpacing:0.5, marginLeft:6,
                  }}
                  title={`${ropeSegs.length} rope/ladder segment${ropeSegs.length===1?"":"s"} (Map.wz ladderRope data)`}
                >
                  ┃ Ropes/Ladders
                </button>
              )}
              {portalInfo && (
                <button
                  onClick={()=>setShowPortals(v=>!v)}
                  style={{
                    background: showPortals ? "#60a5fa22" : "#21262d",
                    border: `1px solid ${showPortals ? "#60a5fa" : "#30363d"}`,
                    borderRadius:999, color: showPortals ? "#60a5fa" : "#9ca3af",
                    fontFamily:"inherit", fontSize:10, fontWeight:700,
                    padding:"2px 9px", cursor:"pointer", letterSpacing:0.5, marginLeft:6,
                  }}
                  title={`${portalInfo.p.length} portal${portalInfo.p.length===1?"":"s"} (Map.wz portal data) -- click a marker to jump to that map`}
                >
                  ◆ Portals
                </button>
              )}
            </div>
            <div style={{ position:"relative", width:"100%", maxWidth:400 }}>
              <img src={mapImg(currentMapId)} alt={mapNameFull || `Map ${currentMapId}`}
                style={{ width:"100%", maxWidth:400, imageRendering:"pixelated", background:"#0d1117", border:"1px solid #30363d", borderRadius:4, display:"block" }}
                onError={e=>{
                  if (!e.target.dataset.triedFallback) {
                    e.target.dataset.triedFallback = "1";
                    e.target.src = mapImgFallback(currentMapId);
                  }
                }} />
              {showSpawns && spawnInfo && (
                <div style={{ position:"absolute", inset:0, pointerEvents:"none" }}>
                  {spawnInfo.s.map(([x, cy], i) => {
                    const div = 2 ** spawnInfo.mag;
                    const px = (x + spawnInfo.centerX) / div;
                    const py = (cy + spawnInfo.centerY) / div;
                    return (
                      <div key={i} style={{
                        position:"absolute",
                        left:`${(px / spawnInfo.cw) * 100}%`,
                        top:`${(py / spawnInfo.ch) * 100}%`,
                        transform:"translate(-50%,-50%)",
                        width:6, height:6, borderRadius:"50%",
                        background:"#ef4444", border:"1px solid #fff8",
                        boxShadow:"0 0 3px #000",
                      }} />
                    );
                  })}
                </div>
              )}
              {showRopes && ropeSegs && spawnInfo && (
                <svg viewBox={`0 0 ${spawnInfo.cw} ${spawnInfo.ch}`} preserveAspectRatio="none"
                  style={{ position:"absolute", inset:0, width:"100%", height:"100%", pointerEvents:"none" }}>
                  {ropeSegs.map(([x, y1, y2], i) => {
                    const div = 2 ** spawnInfo.mag;
                    const px = (x + spawnInfo.centerX) / div;
                    const py1 = (y1 + spawnInfo.centerY) / div;
                    const py2 = (y2 + spawnInfo.centerY) / div;
                    return (
                      <line key={i} x1={px} y1={py1} x2={px} y2={py2}
                        stroke="#f59e0b" strokeWidth={1} strokeDasharray="2,1.5" opacity={0.9} />
                    );
                  })}
                </svg>
              )}
              {showPortals && portalInfo && (
                <div style={{ position:"absolute", inset:0 }}>
                  {portalInfo.p.map(([x, y, tm], i) => {
                    const div = 2 ** portalInfo.mag;
                    const px = (x + portalInfo.centerX) / div;
                    const py = (y + portalInfo.centerY) / div;
                    const targetName = (typeof MAP_NAMES !== "undefined" && MAP_NAMES[tm]) || `Map #${tm}`;
                    return (
                      <div key={i}
                        onClick={e=>{ e.stopPropagation(); navigateTo(tm); }}
                        title={`-> ${targetName} (#${tm})`}
                        style={{
                          position:"absolute",
                          left:`${(px / portalInfo.cw) * 100}%`,
                          top:`${(py / portalInfo.ch) * 100}%`,
                          transform:"translate(-50%,-50%)",
                          width:10, height:10, cursor:"pointer",
                          background:"#60a5fa", border:"1px solid #fff",
                          boxShadow:"0 0 4px #000",
                          clipPath:"polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)",
                        }} />
                    );
                  })}
                </div>
              )}
            </div>
            {/* In-game minimaps show the map name directly under/over the map itself --
                mirrored here so it's obvious at a glance which map this thumbnail is. */}
            <div style={{ marginTop:4, padding:"4px 8px", background:"#0d1117", border:"1px solid #30363d", borderRadius:4, fontSize:11, color:"#e2e8f0", textAlign:"center" }}>
              {mapNameFull || `Map #${currentMapId} (name unavailable)`}
            </div>
          </div>
          <div style={{ flex:"1 1 260px" }}>
            <div style={{ fontSize:10, color:"#6b7280", marginBottom:6, letterSpacing:1 }}>WORLD MAP LOCATION</div>
            {worldImg ? (
              <div style={{ position:"relative", width:"100%", maxWidth:400, border:"1px solid #30363d", borderRadius:4, overflow:"hidden" }}>
                <img src={worldImg} alt={spotInfo.region}
                  style={{ width:"100%", display:"block", background:"#0d1117" }} />
                <div style={{
                  position:"absolute",
                  left:`${((spotInfo.x + region.originX) / region.width) * 100}%`,
                  top:`${((spotInfo.y + region.originY) / region.height) * 100}%`,
                  transform:"translate(-50%,-50%)",
                  width:14, height:14, borderRadius:"50%",
                  background:"#ef4444", border:"2px solid #fff",
                  boxShadow:"0 0 0 3px #ef444488",
                }} />
              </div>
            ) : (
              <div style={{ width:"100%", maxWidth:400, height:200, border:"1px dashed #30363d", borderRadius:4, display:"flex", alignItems:"center", justifyContent:"center", color:"#6b7280", fontSize:11, textAlign:"center", padding:12 }}>
                World map location not available for this map
                <br/>(no resolved spot in the WorldMap.wz extract)
              </div>
            )}
            {/* Same name label under the world map view, so it's unambiguous which
                marker corresponds to which map even at a glance. */}
            <div style={{ marginTop:4, padding:"4px 8px", background:"#0d1117", border:"1px solid #30363d", borderRadius:4, fontSize:11, color:"#e2e8f0", textAlign:"center" }}>
              {mapNameFull || `Map #${currentMapId} (name unavailable)`}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
